"""
Part C step 1 measurement (David, 2026-10-26): the pipeline episode with the arm's gravity from MuJoCo's gravcomp ("physics", the old way) or from the calculated feedforward torque ("feedforward"),
in the normal or the moved layout. Nothing in src/ changes between the runs except the temporary setting ARM_ACTUATOR_SPECS["gravity_comp"], chosen with the environment variable
OPENARM_GRAVITY_COMP (physics | feedforward). The sag correction is ON in both.

    OPENARM_GRAVITY_COMP=physics MUJOCO_GL=egl python experiments/gravity_ff_compare.py --layout normal|moved [--variant plain|zombie_held] --out data/gravity_ff/<name>

Variants: "plain" = the plan as it is (pick, place; the arm goes home empty at the end of the place); "zombie_held" = the pick is flagged end_at_zombie (M074), so the arm goes to the zombie pose HOLDING the
beaker after the pick, then the plan goes on as it can.

Writes <out>/result.json:
  waypoints   every "move" waypoint of the manipulation module when it ends: name, the pad centre's distance to the target (mm) and the angle error (degrees), the time it took;
  home        every joint-space HOME step when it ends: the largest joint error (rad) and the time; plus the arms' state in the first second (empty hands at the zombie pose): largest joint error from the
              hold target and largest joint speed;
  torque      per arm joint (left and right 1..7): the torque the motors needed against their cap (the position actuators' torque limit): typical (median |tau|/cap), peak, share of ticks above 80 % of the cap, ticks
              at the cap, and the moments above 80 % (merged, with the manipulation phase). "needed" = the actuator's applied torque + the gravcomp torque MuJoCo applied for it (physics mode:
              the torque the real motors would have had to give; feedforward mode: gravcomp is 0 and the applied torque already includes the feedforward, so it is what the motors used);
  outcome     the episode's outcome and the plan's status.
Sampled once per tick (150 Hz).
"""

import argparse
import gc
import json
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402
from scipy.spatial.transform import Rotation  # noqa: E402

from src import robot_specs  # noqa: E402
from src.episode_runner import run_episode  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402
from stance_select_moved_test import MOVED  # noqa: E402
from stance_select_test import PLAN4  # noqa: E402

SIDES = ("left", "right")
LOG = {"waypoints": [], "home": [], "first_s": {"max_joint_err_rad": 0.0, "max_joint_speed_rad_s": 0.0}, "n_ticks": 0}


def make_hook(variant):
    def hook(modules, model, data):
        m = modules["manipulation"]
        S, arm = m["state"], m["arm"]
        step0, start0 = m["step"], m["start"]

        def start(segment):
            if variant == "zombie_held" and segment.get("primitive") == "pick":
                segment = {**segment, "end_at_zombie": True}
            return start0(segment)

        def step(obs):
            i0 = S["i"]
            st = S["steps"][i0] if S["steps"] and i0 < len(S["steps"]) else None
            t0 = S["t0"]
            out = step0(obs)
            if st is not None and S["i"] > i0:                          # the waypoint ended on this tick
                took = float(obs["time"] - t0) if t0 is not None else None
                if st["kind"] == "move":
                    p, R = arm.pad_pose(data)
                    LOG["waypoints"].append({"name": st["name"], "prim": S["ctx"].get("primitive"), "err_mm": 1000 * float(np.linalg.norm(p - st["target"])),
                                             "ang_deg": float(np.degrees(np.linalg.norm(Rotation.from_matrix(R.T @ st["R"]).as_rotvec()))), "seconds": took, "t": float(obs["time"])})
                elif st["kind"] == "joints":
                    LOG["home"].append({"name": st["name"], "prim": S["ctx"].get("primitive"), "max_joint_err_rad": float(np.max(np.abs(data.qpos[arm.qadr] - arm.q_cmd))), "seconds": took, "t": float(obs["time"]),
                                        "holding": None})
            return out
        m["step"], m["start"] = step, start
        return modules
    return hook


def make_sampler(task, model, data):
    names = [(s, i) for s in SIDES for i in range(1, 8)]
    aid = [mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, f"{s}_joint{i}_ctrl") for s, i in names]
    dof = [int(model.jnt_dofadr[model.actuator_trnid[a, 0]]) for a in aid]
    cap = np.array([robot_specs.ARM_ACTUATOR_SPECS["joints"][i]["torque_nm"] for _, i in names])
    qadr = [int(model.jnt_qposadr[model.actuator_trnid[a, 0]]) for a in aid]
    rows, phases, times = [], [], []
    S = {"rows": rows, "names": names, "cap": cap}
    hold0 = {}

    def step(obs):
        t = float(data.time)
        LOG["n_ticks"] += 1
        need = data.actuator_force[aid] + data.qfrc_gravcomp[dof]
        rows.append(need.copy())
        times.append(t)
        ep = obs.get("policy")
        phases.append(ep["phase"] if ep else "")
        if "q" not in hold0:
            hold0["q"] = data.qpos[qadr].copy()
        if t - times[0] < 1.0:                                      # empty hands at the zombie pose, the first second
            LOG["first_s"]["max_joint_err_rad"] = max(LOG["first_s"]["max_joint_err_rad"], float(np.max(np.abs(data.qpos[qadr] - hold0["q"]))))
            LOG["first_s"]["max_joint_speed_rad_s"] = max(LOG["first_s"]["max_joint_speed_rad_s"], float(np.max(np.abs(data.qvel[dof]))))
        return None
    S["phases"], S["times"] = phases, times
    return {"name": "gff_sampler", "step": step, "state": S}


def torque_stats(S):
    T = np.abs(np.array(S["rows"]))
    cap = S["cap"]
    frac = T / cap[None, :]
    out = {}
    for j, (s, i) in enumerate(S["names"]):
        f = frac[:, j]
        moments, on = [], None
        for k, v in enumerate(f):
            if v > 0.8 and on is None:
                on = k
            if (v <= 0.8 or k == len(f) - 1) and on is not None:
                moments.append({"t0": S["times"][on], "t1": S["times"][k], "peak_frac": float(f[on:k + 1].max()), "phase": S["phases"][on]})
                on = None
        out[f"{s}{i}"] = {"cap_nm": float(cap[j]), "typical_frac": float(np.median(f)), "peak_frac": float(f.max()), "peak_nm": float(T[:, j].max()), "share_above_80": float(np.mean(f > 0.8)), "ticks_at_cap": int(np.sum(f >= 0.999)), "moments_above_80": moments[:12],
                          "n_moments_above_80": len(moments)}
    return out


def main(args):
    mode = robot_specs.ARM_ACTUATOR_SPECS["gravity_comp"]
    cfg = MOVED if args.layout == "moved" else TASK_CFG
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    print(f"gravity_comp = {mode}; layout {args.layout}; variant {args.variant}", flush=True)
    task = make_pipeline_task(PLAN4, task_cfg=cfg, module_hook=make_hook(args.variant))
    gc.collect()
    sim = load_task(cfg, cameras=True)
    holder = {}

    def extra(m, d):
        holder["s"] = make_sampler(task, m, d)
        return {"gff_sampler": holder["s"]}
    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", extra_sources=extra, stop_after_handoff_s=None)
    state = task["pipeline"]["orchestrator"]["state"]
    ok, diag = task["check_success"](sim.model, sim.data)
    res = {"mode": mode, "layout": args.layout, "variant": args.variant, "outcome": s["outcome"], "failure": state["failure"], "status": state["status"], "beaker_on_hotplate": bool(ok),
           "waypoints": LOG["waypoints"], "home": LOG["home"], "first_s": LOG["first_s"], "torque": torque_stats(holder["s"]["state"]), "n_ticks": LOG["n_ticks"], "sim_time_end": float(sim.data.time)}
    tmp = out / "result.json.tmp"
    tmp.write_text(json.dumps(res, indent=1, default=str))
    tmp.replace(out / "result.json")
    print(f"outcome {s['outcome']} failure {state['failure']} status {state['status']} beaker on hotplate {ok}", flush=True)
    worst = sorted(res["torque"].items(), key=lambda kv: -kv[1]["peak_frac"])[:4]
    print("highest torque peaks (share of cap):", [(k, round(v["peak_frac"], 2)) for k, v in worst], flush=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--layout", choices=("normal", "moved"), default="normal")
    ap.add_argument("--variant", choices=("plain", "zombie_held"), default="plain")
    ap.add_argument("--out", required=True)
    main(ap.parse_args())
